def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def dfs(x, y, path, steps):
        if steps == k:
            return path

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                new_path = path + [grid[nx][ny]]
                result = dfs(nx, ny, new_path, steps + 1)
                if result:
