def solve(s):
    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        return s[::-1]

    result = []
    for char in s:
        if char.isalpha():
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
        else:
            result.append(char)

    return ''.join(result)

import hashlib

def string_to_md5(text):
    if not text:
        return None

    md5_hash = hashlib.md5(text.encode()).hexdigest()
    return md5_hash

