def pancake_sort(arr):
    n = len(arr)
    for i in range(n, 0, -1):
        # Find the index of the maximum element in arr[0..i-1]
        max_index = 0
        for j in range(1, i):
            if arr[j] > arr[max_index]:
                max_index = j

        # Flip the array from start to max_index
        flip(arr, 0, max_index)

        # Flip the array from start to i-1
        flip(arr, 0, i-1)

    return arr

def flip(arr, start, end):
    while start < end:
        arr[start], arr[end] = arr[end], arr[start]
        start += 1
        end -= 1

