def set_left_most_unset_bit(n):
    if n == 0:
        return 1

    # Find the position of the rightmost unset bit
    pos = 0
    while (n & 1) == 1:
        n >>= 1
        pos += 1

    # Set the leftmost unset bit
    return n | (1 << pos)

