def maxAverageOfPath(matrix):
    n = len(matrix)
    if n == 0:
        return 0

    # Initialize dp table
    dp = [[0] * n for _ in range(n)]

    # Fill the first row and first column
    for i in range(n):
        dp[0][i] = matrix[0][i]
        dp[i][0] = matrix[i][0]

    # Fill the rest of the dp table
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = matrix[i][j] + max(dp[i-1][j], dp[i][j-1])

    # Calculate the maximum average
    max_avg = float('-inf')
    for i in range(n):
        for j in range(n):
            avg = dp[i][j] / (i+1) * (j+1)
            max_avg = max(max_avg, avg)

    return max_avg

