    min_diff = float('inf')  # Initialize min_diff to infinity

    for i in range(n - 1):
        diff = arr[i + 1] - arr[i]  # Calculate the difference between consecutive elements
        if diff < min_diff:
            min_diff = diff  # Update min_diff if current difference is smaller

    return min_diff

