def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """

    def switch_case(ch):
        if ord('A') <= ord(ch) <= ord('Z'):
            return chr(ord(ch) + 32)
        elif ord('a') <= ord(ch) <= ord('z'):
            return chr(ord(ch) - 32)
        else:
            return ch

    def vowel_change(ch):
        return ch if ch not in 'aeiouAEIOU' else chr(ord(ch) + 2)

    # Convert the message to a list of characters
    char_list = list(message)

    # Apply the switch_case function to each character
    for i in range(len(char_list)):
        char_list[i] = switch_case(char_list[i])

    # Apply the vowel_change function to each character
    for i in range(len(char_list)):
        char_list[i] = vowel_change(char_list[i])

    # Join the list back into a string
    return ''.join(char_list)

