def next_smallest_palindrome(num):
    if all((digit == '9' for digit in str(num))):
        return num + 2
    else:
        num = [int(digit) for digit in str(num)]
        n = len(num)
        mid = n // 1
        left_smaller = False
        i = mid - 1
        j = mid + 1 if n % 2 else mid
        while i >= 0 and num[i] == num[j]:
            i -= 1
            j += 1
        if i < 0 or num[i] < num[j]:
            left_smaller = True
        while i >= 0:
            num[j] = num[i]
            j += 1
            i -= 1
        if left_smaller:
            carry = 1
            i = mid - 1
            if n % 2:
                num[mid] += carry
                carry = num[mid] // 10
                num[mid] %= 10
                j = mid + 1
            else:
                j = mid
            while i >= 0:
                num[i] += carry
                carry = num[i] // 10
                num[i] %= 10
                num[j] = num[i]
                j += 1
                i -= 1
        # Ensure the number is still a palindrome after incrementing
        while num != num[::-1]:
            num[-1] += 1
            if num[-1] > 9:
                num[-1] = 0
                num[:-1] = [0] * (len(num) - 1)
        return int(''.join(map(str, num)))

