import heapq

def merge_sorted_list(num1, num2, num3):
    # 将列表转换为堆以方便排序
    heap = []
    for lst in [num1, num2, num3]:
        for item in lst:
            heapq.heappush(heap, item)

    # 使用 heapq 排序堆中的元素
    merged_list = []
    while heap:
        merged_list.append(heapq.heappop(heap))

    return merged_list

