import math

def sum(a, b):
    sum = 0
    n = math.gcd(a, b)
    N = int(math.sqrt(n)) + 1
    for i in range(1, N):
        if n % i == 0:
            sum += i
            if i != n // i:
                sum += n // i
    return sum

def magic_square_test(my_matrix):
    n = len(my_matrix)
    s = sum(my_matrix[0])

    # Check rows
    for row in my_matrix:
        if sum(row) != s:
            return False

    # Check columns
    for col in range(n):
        if sum(my_matrix[row][col] for row in range(n)) != s:
            return False

    # Check main diagonal
    if sum(my_matrix[i][i] for i in range(n)) != s:
        return False

    # Check anti-diagonal
    if sum(my_matrix[i][n-i-1] for i in range(n)) != s:
        return False

    return True

