    arr_len = len(nums)
    while arr_len > 1:
        # 找到最大值的位置
        mi = nums.index(max(nums[:arr_len]))

        # 如果最大值不是当前数组的最后一个元素，则进行一次反转
        if mi != arr_len - 1:
            nums = nums[mi::-1] + nums[mi + 1:]

