def large_product(nums1, nums2, N):
    result = []
    for x in nums1:
        for y in nums2:
            product = x * y
            if len(result) < N:
                result.append(product)
            elif product > result[-1]:
                result.pop()
                result.append(product)
    return sorted(result, reverse=True)[:N]

