def get_max_sum(n):
    if n <= 0:
        return 0

    res = [0] * (n + 1)
    for i in range(1, n + 1):
        res[i] = max(res[i // 2] + res[i // 3] + res[i // 4] + res[i // 5], i)

    return res[n]

