def max_subarray_product(arr):
    if not arr:
        return 0

    max_so_far = min_ending = max_ending = arr[0]

    for n in arr[1:]:
        if n < 0:
            min_ending, max_ending = max_ending, min_ending

        min_ending = min(n, min_ending * n)
        max_ending = max(n, max_ending * n)

        max_so_far = max(max_so_far, max_ending)

    return max_so_far

