import numpy as np

def maxAverageOfPath(cost):
    N = len(cost)
    if N == 0:
        return 0

    dp = [[0 for _ in range(N + 1)] for _ in range(N + 1)]
    dp[0][0] = cost[0][0]

    # Fill the first row
    for j in range(1, N):
        dp[0][j] = dp[0][j - 1] + cost[0][j]

    # Fill the first column
    for i in range(1, N):
        dp[i][0] = dp[i - 1][0] + cost[i][0]

    # Fill the rest of the DP table
    for i in range(1, N):
        for j in range(1, N):
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + cost[i][j]

    # Calculate the maximum average path
    max_avg = 0
    for i in range(N):
        for j in range(N):
            if i == 0 and j == 0:
                continue
            if i == 0:
                avg = dp[i][j - 1] / (j + 1)
            elif j == 0:
                avg = dp[i - 1][j] / (i + 1)
            else:
                avg = (dp[i - 1][j] + dp[i][j - 1]) / (i + j + 1)
            max_avg = max(max_avg, avg)

    return max_avg

