    dp = [[0 for _ in range(N + 1)] for _ in range(N + 1)]
    dp[0][0] = cost[0][0]

    # Fill the first row
    for j in range(1, N):
        dp[0][j] = dp[0][j - 1] + cost[0][j]

    # Fill the first column
    for i in range(1, N):
        dp[i][0] = dp[i - 1][0] + cost[i][0]

    # Initialize max_avg outside the loop
    max_avg = float('-inf')

    # Fill the rest of the DP table
    for i in range(1, N):
        for j in range(1, N):
            if i == 0 and j == 0:
                continue
            if i == 0:
                avg = dp[i][j - 1] / (j + 1) if j > 0 else 0
            elif j == 0:
                avg = dp[i - 1][j] / (i + 1) if i > 0 else 0
            else:
                avg = (dp[i - 1][j] + dp[i][j - 1]) / (i + j + 1)
            max_avg = max(max_avg, avg)

    return max_avg

